INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '查询智能体会话','ai:session:list:api','api',p.id,'/v1/agent-console/agents/{id}/sessions','GET','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:session:list:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '创建智能体会话','ai:session:create:api','api',p.id,'/v1/agent-console/agents/{id}/sessions','POST','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:session:create:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '查询会话消息','ai:session:messages:api','api',p.id,'/v1/agent-console/agents/{id}/sessions/{sessionId}/messages','GET','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:session:messages:api' AND del_flag=0);
INSERT INTO t_role_permission(role_id,permission_id,create_time,update_time,del_flag) SELECT r.id,p.id,NOW(),NOW(),0 FROM t_role r CROSS JOIN t_permission p WHERE r.code='superAdmin' AND r.status='active' AND r.del_flag=0 AND p.code IN ('ai:session:list:api','ai:session:create:api','ai:session:messages:api') AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_role_permission rp WHERE rp.role_id=r.id AND rp.permission_id=p.id AND rp.del_flag=0);
